DROP TABLE IF EXISTS `split_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `split_history` (
  `split_id` int NOT NULL AUTO_INCREMENT,
  `show_qbo_id` int NOT NULL,
  `show_name` varchar(100) DEFAULT NULL,
  `vendor_qbo_id` int DEFAULT NULL,
  `vendor_name` varchar(100) DEFAULT NULL,
  `partner_pct_ads` decimal(4,2) DEFAULT NULL,
  `partner_pct_programmatic` decimal(4,2) DEFAULT NULL,
  `effective_date` date DEFAULT NULL,
  PRIMARY KEY (`split_id`),
  KEY `show_qbo_id` (`show_qbo_id`),
  KEY `show_name` (`show_name`),
  KEY `vendor_id` (`vendor_qbo_id`),
  KEY `vendor_name` (`vendor_name`),
  KEY `idx_split_history_show_vendor_eff` (`show_qbo_id`,`vendor_qbo_id`,`effective_date`),
  CONSTRAINT `split_history_ibfk_1` FOREIGN KEY (`show_qbo_id`) REFERENCES `allclass` (`id`),
  CONSTRAINT `split_history_ibfk_2` FOREIGN KEY (`vendor_qbo_id`) REFERENCES `allvendors` (`id`),
  CONSTRAINT `split_history_chk_1` CHECK (((`partner_pct_ads` >= 0) and (`partner_pct_ads` <= 1))),
  CONSTRAINT `split_history_chk_2` CHECK (((`partner_pct_programmatic` >= 0) and (`partner_pct_programmatic` <= 1)))
) ENGINE=InnoDB AUTO_INCREMENT=249 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
