/*!50001 VIEW `revenue_ledger` AS select `ac`.`name` AS `invoice_classref_name`,`i`.`customerref_name` AS `customer_invoice`,`i`.`id` AS `inv_id`,`i`.`txndate` AS `invoice_date`,`i`.`line_description` AS `invoice_description`,`i`.`totalamt` AS `invoice_amount`,`i`.`linkedtxn_txnid` AS `linkedtxn_txnid`,`ps`.`payment_amounts` AS `payment_amounts`,`ps`.`payment_dates` AS `payment_dates`,`i`.`docnumber` AS `invoice_doc_number`,`i`.`classref_value` AS `invoice_classref_value`,`i`.`line_itemrefname` AS `invoice_itemrefname`,`sh`.`effective_date` AS `effective_date`,`sh`.`vendor_qbo_id` AS `vendor_qbo_id`,lower(`i`.`line_itemrefname`) AS `item_lower`,(case when (lower(`i`.`line_itemrefname`) like '%programmatic%') then (1.0 - `sh`.`partner_pct_programmatic`) else (1.0 - `sh`.`partner_pct_ads`) end) AS `evergreen_percentage`,(case when (lower(`i`.`line_itemrefname`) like '%programmatic%') then `sh`.`partner_pct_programmatic` else `sh`.`partner_pct_ads` end) AS `partner_percentage`,round((case when ((lower(`i`.`line_itemrefname`) like '%programmatic%') and (`sh`.`partner_pct_programmatic` is not null)) then (coalesce(`ps`.`tot_payment_amount`,0) * (1.0 - `sh`.`partner_pct_programmatic`)) when (`sh`.`partner_pct_ads` is not null) then (coalesce(`ps`.`tot_payment_amount`,0) * (1.0 - `sh`.`partner_pct_ads`)) end),2) AS `evergreen_compensation`,round((case when ((lower(`i`.`line_itemrefname`) like '%programmatic%') and (`sh`.`partner_pct_programmatic` is not null)) then (coalesce(`ps`.`tot_payment_amount`,0) * `sh`.`partner_pct_programmatic`) when (`sh`.`partner_pct_ads` is not null) then (coalesce(`ps`.`tot_payment_amount`,0) * `sh`.`partner_pct_ads`) end),2) AS `partner_compensation`,coalesce(`ps`.`tot_payment_amount`,0) AS `tot_payment_amounts`,(`i`.`totalamt` - coalesce(`ps`.`tot_payment_amount`,0)) AS `outstanding_balance`,round(((`i`.`totalamt` - coalesce(`ps`.`tot_payment_amount`,0)) * (case when (lower(`i`.`line_itemrefname`) like '%programmatic%') then `sh`.`partner_pct_programmatic` else `sh`.`partner_pct_ads` end)),2) AS `partner_comp_waiting` from (((`allinvoices` `i` left join (select `jt`.`TxnId` AS `TxnId`,sum(`jt`.`Amount`) AS `tot_payment_amount`,json_arrayagg(`jt`.`Amount`) AS `payment_amounts`,json_arrayagg(`p`.`txndate`) AS `payment_dates` from (`allpayments` `p` join json_table(`p`.`line`, '$[*]' columns (`Amount` decimal(10,2) path '$.Amount', `TxnId` varchar(50) character set utf8mb4 path '$.LinkedTxn[0].TxnId')) `jt`) group by `jt`.`TxnId`) `ps` on((cast(`i`.`id` as char charset utf8mb4) = `ps`.`TxnId`))) left join lateral (select `sh1`.`split_id` AS `split_id`,`sh1`.`show_qbo_id` AS `show_qbo_id`,`sh1`.`show_name` AS `show_name`,`sh1`.`vendor_qbo_id` AS `vendor_qbo_id`,`sh1`.`vendor_name` AS `vendor_name`,`sh1`.`partner_pct_ads` AS `partner_pct_ads`,`sh1`.`partner_pct_programmatic` AS `partner_pct_programmatic`,`sh1`.`effective_date` AS `effective_date` from `split_history` `sh1` where ((`sh1`.`show_qbo_id` = `i`.`classref_value`) and (`sh1`.`effective_date` <= `i`.`txndate`)) order by `sh1`.`effective_date` desc limit 1) `sh` on(true)) join `allclass` `ac` on((`i`.`classref_value` = `ac`.`id`))) */;
